#!/usr/bin/env node
// Writes src/ui/emoji-picker/emoji-data.ts, the picker's lazily loaded data, from two development
// dependencies that never reach the package: unicode-emoji-json (CLDR names, groups, order) and
// emojilib (keywords).
//   node scripts/build-emoji.mjs           regenerate
//   node scripts/build-emoji.mjs --check   fail if the generated file is out of date
//
// Each group is one string, a row per emoji: `<emoji> [~]<name>[|<keyword> <keyword>]`, where `~`
// marks an emoji that takes one skin tone. Keeping the whole thing a few strings is what makes it
// small: 65 KB of source, about 23 KB after gzip. Each extra keyword per emoji costs about 3.7 KB
// of gzip, so two is the cap; names alone are 15 KB, but miss searches such as "happy" or "love".
import { readFileSync, writeFileSync } from "node:fs"
import { createRequire } from "node:module"
import { join, resolve } from "node:path"

const root = resolve(import.meta.dirname, "..")
const require = createRequire(import.meta.url)
const output = join(root, "src/ui/emoji-picker/emoji-data.ts")

/** Newer emoji show as an empty box on the systems the library supports, and the glyph comes from the system font. */
const MAX_EMOJI_VERSION = 15
const MAX_KEYWORDS = 2
const GROUPS = {
  "Smileys & Emotion": "smileys",
  "People & Body": "people",
  "Animals & Nature": "nature",
  "Food & Drink": "food",
  "Travel & Places": "travel",
  Activities: "activities",
  Objects: "objects",
  Symbols: "symbols",
  Flags: "flags",
}

const groups = require("unicode-emoji-json/data-by-group.json")
const keywords = require("emojilib/dist/emoji-en-US.json")
const list = Array.isArray(groups) ? groups : Object.entries(groups).map(([name, emojis]) => ({ name, emojis }))

/** A sequence with two people takes two tones, which is more than a picker's one choice can say. */
const oneTone = (emoji) => (emoji.match(/\p{Emoji_Modifier_Base}/gu) ?? []).length === 1

function row({ emoji, name, skin_tone_support: tones }) {
  const words = name.toLowerCase().split(/[^a-z0-9]+/)
  const extra = (keywords[emoji] ?? keywords[emoji.replace(/️/g, "")] ?? [])
    .map((word) => word.toLowerCase())
    .filter((word) => /^[a-z0-9]{3,}$/.test(word) && !words.includes(word))
    .slice(0, MAX_KEYWORDS)
  const search = extra.length ? `|${extra.join(" ")}` : ""
  return `${emoji} ${tones && oneTone(emoji) ? "~" : ""}${name}${search}`
}

const data = Object.fromEntries(
  list.map(({ name, emojis }) => {
    const id = GROUPS[name]
    if (!id) throw new Error(`build-emoji: unknown group ${name}`)
    return [id, emojis.filter((emoji) => Number(emoji.emoji_version) <= MAX_EMOJI_VERSION).map(row).join("\n")]
  }),
)

const lines = Object.entries(data).map(([id, rows]) => `  ${id}: ${JSON.stringify(rows)},`)
// Typed as plain strings: `as const` would repeat every byte of the data in the declaration file.
const ids = Object.keys(data).map((id) => JSON.stringify(id)).join(" | ")
const text = `// Generated by scripts/build-emoji.mjs (pnpm emoji). Do not edit.\n/* oxlint-disable */\nexport const EMOJI_DATA: Record<${ids}, string> = {\n${lines.join("\n")}\n}\n`

if (process.argv.includes("--check")) {
  let current = ""
  try {
    current = readFileSync(output, "utf8")
  } catch {}
  if (current !== text) {
    console.error("build-emoji: src/ui/emoji-picker/emoji-data.ts is out of date. Run pnpm emoji.")
    process.exit(1)
  }
  console.log("emoji: data matches its sources")
} else {
  writeFileSync(output, text)
  console.log(`emoji: ${Buffer.byteLength(text)} bytes`)
}
